function countFoundPatterns(patterns: string[], word: string): number {
  let count = 0;
  for (const p of patterns) {
    for (let i = 0; i + p.length <= word.length; i++) {
      let j = 0;
      while (j < p.length && word[i + j] === p[j]) j++;
      if (j === p.length) { count++; break; }
    }
  }
  return count;
}

