function countFoundPatterns(patterns: string[], word: string): number {
  const root: Map<string, any> = new Map();
  for (let i = 0; i < word.length; i++) {
    let node = root;
    for (let j = i; j < word.length; j++) {
      if (!node.has(word[j])) node.set(word[j], new Map());
      node = node.get(word[j]);
    }
  }
  let count = 0;
  for (const p of patterns) {
    let node: Map<string, any> | undefined = root;
    for (const ch of p) { node = node.get(ch); if (!node) break; }
    if (node) count++;
  }
  return count;
}

